#!/usr/bin/env bash
# Build the pmOS-config kernel on this machine. Uses the config generated by
# pmaports-ref/.../gen-config.sh, which carries the pmOS delta: VT,
# DEVTMPFS_MOUNT (needed for /dev/kmsg before init), SPLASH_CONSOLE,
# PANIC_ON_OOPS off, and rdinit=/pmos-init.
set -euo pipefail
TOOLCHAIN="${TOOLCHAIN:-$HOME/Desktop/Projects/phone-pmos/toolchains/clang-r510928}"
[ -x "$TOOLCHAIN/bin/clang" ] || { echo "ERROR: need AOSP clang r510928"; exit 1; }
export PATH="$TOOLCHAIN/bin:$HOME/bin:$PATH"
KROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
OUT="$KROOT/out-pmos"
CFG=$HOME/Desktop/Projects/phone-pmos/pmaports-ref/device/testing/linux-samsung-pa2q/config-samsung-pa2q.aarch64
export ARCH=arm64 SUBARCH=arm64
export CROSS_COMPILE=aarch64-linux-gnu- CLANG_TRIPLE=aarch64-linux-gnu-
export KCFLAGS="-O2 -pipe -Wno-error -D__ANDROID_COMMON_KERNEL__"
export KCPPFLAGS="$KCFLAGS"
MK=(make O="$OUT" ARCH=arm64 SUBARCH=arm64 LLVM=1 LLVM_IAS=1 LD=ld.lld HOSTLD=ld.lld
    AR=llvm-ar NM=llvm-nm OBJCOPY=llvm-objcopy OBJDUMP=llvm-objdump OBJSIZE=llvm-size)
cd "$KROOT"
[ -e drivers/kernelsu/Kconfig ] || { mkdir -p drivers/kernelsu; echo "# stub" > drivers/kernelsu/Kconfig; : > drivers/kernelsu/Makefile; }
mkdir -p "$OUT"; cp "$CFG" "$OUT/.config"
"${MK[@]}" olddefconfig >/dev/null
for o in CFI_CLANG SHADOW_CALL_STACK KASAN_HW_TAGS SPLASH_CONSOLE VT DEVTMPFS_MOUNT; do
  grep -qE "^CONFIG_$o=y" "$OUT/.config" || { echo "ERROR: CONFIG_$o not set"; exit 1; }
done
grep -q "rdinit=/pmos-init" "$OUT/.config" || { echo "ERROR: rdinit missing from cmdline"; exit 1; }
echo "config OK: mitigations + splashcon + rdinit present"
"${MK[@]}" -j"$(nproc)" Image
echo "==> $OUT/arch/arm64/boot/Image ($(stat -c%s "$OUT/arch/arm64/boot/Image") bytes)"
